function UpdateRibbonSegments(segments, p0, p1, p2) {
    var count = segments.length;
    if (count < 1) {
        return;
    }
    for (var i = 0; i < count; i++) {
        var t = (count === 1) ? 0 : i / (count - 1);
        var it = 1 - t;
        var x = it * it * p0[0] + 2 * it * t * p1[0] + t * t * p2[0];
        var y = it * it * p0[1] + 2 * it * t * p1[1] + t * t * p2[1];
        var t2 = Math.min(1, t + 0.02);
        var it2 = 1 - t2;
        var x2 = it2 * it2 * p0[0] + 2 * it2 * t2 * p1[0] + t2 * t2 * p2[0];
        var y2 = it2 * it2 * p0[1] + 2 * it2 * t2 * p1[1] + t2 * t2 * p2[1];
        var dx = x2 - x;
        var dy = y2 - y;
        var len = Math.max(1, Math.sqrt(dx * dx + dy * dy));
        var ang = Math.atan2(dy, dx) * (180 / Math.PI);
        var seg = segments[i];
        seg.style.width = len + "px";
        seg.style.transform = "rotateZ(" + ang + "deg)";
        seg.style.position = x + "px " + y + "px 0px";
    }
}

function UpdateShop1Ribbon(panel, endX, endY) {
