    if (!base || base.length < 3) {
        ribbon.container.visible = false;
        return;
    }
    var leftWorld = [base[0] - 100, base[1], base[2]];
    var rightWorld = [base[0] + 100, base[1], base[2]];
    var left = WorldToPanelXY(leftWorld, panel);
    var right = WorldToPanelXY(rightWorld, panel);
    if (!left || !right) {
        ribbon.container.visible = false;
        return;
    }
    ribbon.container.visible = true;
    var midStart = [(left[0] + right[0]) * 0.5, (left[1] + right[1]) * 0.5];
    var end = [endX, endY];
    var dx = end[0] - midStart[0];
    var dy = end[1] - midStart[1];
    var dist = Math.max(1, Math.sqrt(dx * dx + dy * dy));
    var useRight = dx >= 0;
    var nx = useRight ? (dy / dist) : (-dy / dist);
    var ny = useRight ? (-dx / dist) : (dx / dist);
    var bend = Math.min(120, dist * 0.25);
    var ctrlMid = [midStart[0] + nx * bend, midStart[1] + ny * bend];
    var ctrlLeft = [left[0] + nx * bend, left[1] + ny * bend];
    var ctrlRight = [right[0] + nx * bend, right[1] + ny * bend];

    UpdateRibbonSegments(ribbon.left, left, ctrlLeft, end);
    UpdateRibbonSegments(ribbon.right, right, ctrlRight, end);
}

